# - LIBRARY_CONTENT: 25
# - FEEDBACK_CHITCHAT: 15
# Total = 200
# Escalation: 70 ESCALATE (~35%), 130 AUTO_HANDLE (~65%)

data = []

def add_example(idx, tweet, intent, escalation, reason, ref_reply, requires_dm, sentiment, is_edge_case=False, edge_case_type="standard", rel=5, gro=5, bv=5, esc=5):
    data.append({
        "id": f"GOLD-{idx:03d}",
        "incoming_tweet": tweet,
        "gold_intent": intent,
        "gold_escalation": escalation,
        "gold_escalation_reason": reason,
        "historical_reference_reply": ref_reply,
        "requires_dm": requires_dm,
        "customer_sentiment": sentiment,
        "is_edge_case": is_edge_case,
        "edge_case_type": edge_case_type,
        "human_scores": {
            "relevance": rel,
            "groundedness": gro,
            "brand_voice": bv,
            "escalation_correctness": esc
        }
    })

